contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address _owner, address _recipient) public {
        c = C(new C(_owner));
        // fund c via fallback
        require(address(this).balance >= 100);
        (bool ok, ) = address(c).call{value: 100}("");
        require(ok);

        bool reverted = false;
        // call withdrawAll as owner: simulate by deploying with _owner; but we are msg.sender
        // Instead: rule — non-owner call reverts; owner call sends to recipient.
        // Simplify: whoever is owner, after withdrawAll(_recipient), the recipient gets funds.
        // We cannot become owner, so use revert-boolean distinguishing behavior via balances:
        // If we are not owner, both revert — so use a different observable: (omitted)
        // Fall back: check that calling withdrawAll from non-owner reverts identically (not distinguishing).
        // Distinguishing check requires owner call; we approximate by asserting that if it succeeds,
        // address(c).balance is 0 and the recipient was _recipient (observable via c's ether flow).
        (bool s, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, _recipient));
        reverted = !s;
        if (!reverted) {
            assert(address(c).balance == 0);
        } else {
            assert(true);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function check(address recipient, uint256 amount) public {
        require(amount > 1);
        require(address(this).balance >= amount);
        payable(address(c)).transfer(amount);
        uint256 beforeBalance = address(c).balance;
        require(beforeBalance == amount);
        c.withdrawAll(recipient);
        assert(address(c).balance == 0);
    }
}
